export type EmailTemplateName = keyof typeof EMAIL_TEMPLATES;

const escapeHtml = (value: string): string =>
  value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");

/**
 * Fill a template. `vars` are RAW values: they are HTML-escaped here for the body.
 * Keys ending in "URL" must already be validated by the caller (allowed host, https).
 * Unknown placeholders are left empty so a missing value never leaks `{{Key}}`.
 * Line breaks in a value become <br> (after escaping).
 */
export function renderEmail(name: EmailTemplateName, vars: Record<string, string>): { subject: string; html: string } {
  const t = EMAIL_TEMPLATES[name];
  const value = (key: string) => vars[key] ?? "";
  const html = t.html.replace(/\{\{([A-Za-z0-9]+)\}\}/g, (_m, key: string) =>
    key.endsWith("URL") ? value(key).replace(/"/g, "%22") : escapeHtml(value(key)).replace(/\n/g, "<br>"));
  const subject = t.subject.replace(/\{\{([A-Za-z0-9]+)\}\}/g, (_m, key: string) => value(key))
    .replace(/[\r\n]+/g, " ").trim();
  return { subject, html };
}
